#include <iostream>
#include <algorithm>
using namespace std;

long long solveNumber(long long n) {
    if (n == 0) return 0;
    long long base = 1, length = 1;
    while (base <= n) {
        base = base * 10 + 1;
        length++;
    }
    length--;
    base = (base - 1) / 10;
    if (base == n) return length;
    long long min_steps = (1LL << 63);
    if ((base * 10 + 1 - n) < n) {
        min_steps = solveNumber(base * 10 + 1 - n) + length + 1;
    }
    long long factor = 1;
    long long candidate;
    while (base * factor <= n) {
        candidate = base * factor;
        factor++;
    }
    factor--;
    long long alternative_option = solveNumber(n - candidate) + length * (factor - 1);
    return min(min_steps, alternative_option);
}

int main() {
    ios::sync_with_stdio(false);
    long long num;
    cin >> num;
    cout << solveNumber(num);
    return 0;
}
